
import { greet } from "./js/greet.js";
import { add } from "./js/math.js";
import multiply from "./js/math.js";
import { updateOutput } from "./js/dom.js";

const btn = document.getElementById("btn");
const input = document.getElementById("nameInput");

btn.addEventListener("click", () => {
  const name = input.value || "Гість";

  const message = greet(name);
  const sum = add(2, 3);
  const product = multiply(2, 3);

  updateOutput(`${message} | 2+3=${sum}, 2×3=${product}`);
});
